+test("-h stampa lo stesso aiuto di --help, con codice 0", () => {
+  const dir = mkdtempSync(join(tmpdir(), "postit-aiuto-test-"));
+  const run = (...args: string[]) => Bun.spawnSync([process.execPath, cli, ...args, "--dati", dir], { env: { ...process.env }, stdout: "pipe", stderr: "pipe" });
+  try {
+    const lungo = run("--help");
+    const corto = run("-h");
+    expect(corto.exitCode).toBe(0);
+    expect(corto.stdout.toString()).toBe(lungo.stdout.toString());
+    expect(corto.stdout.toString()).toContain("postit — archivio locale");
+  } finally { rmSync(dir, { recursive: true }); }
